using System;using System.Linq;using System.IO;using System.Text.Json;using System.Collections.Generic;using System.Reflection;using System.Security.Cryptography;using WorldGenesis.Simulation;using WorldGenesis.Tests;
static class Scenarios {static string Hash(string p)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p)));public static int Run(string output){var options=new JsonSerializerOptions{IncludeFields=true,WriteIndented=true};FaunaBalanceScenarios.Clone=w=>JsonSerializer.Deserialize<WorldState>(JsonSerializer.Serialize(w,options),options);FaunaBalanceScenarios.Snapshot=w=>JsonSerializer.Serialize(w,options);WildlifeScenarios.Clone=FaunaBalanceScenarios.Clone;WildlifeScenarios.Snapshot=FaunaBalanceScenarios.Snapshot;AgricultureScenarios.Clone=FaunaBalanceScenarios.Clone;AgricultureScenarios.Snapshot=FaunaBalanceScenarios.Snapshot;var before=Directory.GetFiles("WorldGenesis/Assets/_Project/Scripts/Simulation","*.cs",SearchOption.AllDirectories).ToDictionary(p=>p,p=>Hash(p));var results=new List<object>();int failed=0;foreach(var type in new[]{typeof(FaunaBalanceScenarios),typeof(BuildingPlacementScenarios),typeof(WildlifeScenarios),typeof(AgricultureScenarios)})foreach(var m in type.GetMethods(BindingFlags.Static|BindingFlags.Public)){if(m.ReturnType!=typeof(void)||m.GetParameters().Length!=0)continue;try{m.Invoke(null,null);results.Add(new{name=m.Name,passed=true});Console.WriteLine("PASS "+m.Name);}catch(Exception ex){failed++;string error=(ex.InnerException??ex).ToString();results.Add(new{name=m.Name,passed=false,error});Console.WriteLine("FAIL "+m.Name+": "+error);}}bool unchanged=before.All(kv=>Hash(kv.Key)==kv.Value);Directory.CreateDirectory(Path.GetDirectoryName(output));File.WriteAllText(output,JsonSerializer.Serialize(new{utc=DateTime.UtcNow,tests=results.Count,failed,sourceUnchanged=unchanged,sourceSHA256=before,results},options));Console.WriteLine((results.Count-failed)+"/"+results.Count+" PASS; sourceUnchanged="+unchanged);return failed==0&&unchanged?0:1;}}
